#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 long long countFairPairs(vector<int>& nums,int lower,int upper){
  sort(nums.begin(),nums.end());
  auto count=[&](long long bound){long long ans=0;int l=0,r=nums.size()-1;
   while(l<r){if((long long)nums[l]+nums[r]<=bound){ans+=r-l;++l;}else --r;}return ans;};
  return count(upper)-count((long long)lower-1);
 }
};
